                                    isActive 
                                      ? "bg-[#1463FF]" 
                                      : "bg-[#112F82] hover:bg-[#173EAD]"
                                  } ${option.hasSub ? "h-[52px]" : "h-[36px]"} ${
                                    isLast ? "rounded-b-[8px]" : ""
                                  }`}
