                                    </span>
                                    {option.hasSub && (
                                      <span className={`font-manrope text-[10px] font-medium leading-[14px] tracking-[0.02em] ${
                                        isActive ? "text-white" : "text-[#A5B8EF]"
                                      }`}>
                                        {option.subtext}
                                      </span>
                                    )}
                                  </div>
                                </button>
                              );
                            })}
                          </div>
                        </div>
