                            <>
                              <div className="flex items-center gap-[2px] w-[42px] h-[20px] flex-none">
                                <img src="/images/visa.svg" alt="Credit Card" className="w-[42px] h-[20px]" />
                              </div>
                              <div className="flex items-center gap-[8px] w-full sm:w-[288px] h-[19px]">
