                                    ? "bg-[#173EAD] border-2 border-[#1463FF]"
                                    : "bg-[#112F82]"
                                }`}
                              >
                                {selectedAmountOption === "custom" ? (
                                  <input
                                    type="text"
                                    value={customAmount}
                                    onChange={(e) => setCustomAmount(e.target.value)}
